BEGIN;

-- ZAID Tender AI Phase 1, batch 3: saved analyses (version 2 projection). FEATURE-BRANCH
-- MIGRATION, applied after 20261118100000 (tracking). It must not be merged to main or applied
-- to any shared/production database while the production migration reconciliation is
-- unresolved, and it is deliberately NOT in src/db/production-pending-migration-allowlist.ts.
--
-- The authoritative version-2 validation is the hand-written Gateway validator
-- (src/tender/analysis-contract.ts, parity-tested against fixtures generated by the Tender AI
-- contract). The checks below are a SECOND line of defence: they pin the denormalised columns to
-- the stored payload and refuse the self-contradictions that matter most (coverage/status,
-- counts, truncation flag). They never repair or convert a payload.

-- 1. The audit table now also records saved-analysis mutations. The table is append-only; only
--    its CHECK constraints change. Existing rows (tracking events) remain valid.
ALTER TABLE ghm.tender_audit_event DROP CONSTRAINT tender_audit_operation_valid;
ALTER TABLE ghm.tender_audit_event ADD CONSTRAINT tender_audit_operation_valid
  CHECK (operation IN (
    'tender.tracking.create', 'tender.tracking.update', 'tender.tracking.archive', 'tender.tracking.delete',
    'tender.analysis.create', 'tender.analysis.delete'
  ));
ALTER TABLE ghm.tender_audit_event DROP CONSTRAINT tender_audit_resource_type_valid;
ALTER TABLE ghm.tender_audit_event ADD CONSTRAINT tender_audit_resource_type_valid
  CHECK (resource_type IN ('tracking', 'analysis'));

-- 2. Second-line structural check of a stored projection. NULL means "no problem found".
--    IMMUTABLE so it can back a CHECK constraint.
CREATE OR REPLACE FUNCTION ghm.tender_analysis_result_problem(p_result jsonb)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog, ghm
AS $problem$
DECLARE
  v_total integer;
  v_processed integer;
  v_status text;
  v_actual_processed integer;
  v_any_omitted boolean;
BEGIN
  IF p_result IS NULL OR jsonb_typeof(p_result) <> 'object' THEN RETURN 'not_an_object'; END IF;
  -- jsonb::text carries spaces after separators, so the compact 12 KiB limit is enforced by the
  -- Gateway; this is only a sanity ceiling.
  IF octet_length(p_result::text) > 20000 THEN RETURN 'too_large'; END IF;
  IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_result) AS k) IS DISTINCT FROM ARRAY[
    'coverage', 'importantDates', 'missingInformation', 'omitted', 'projectionVersion', 'requirements',
    'source', 'summary', 'summaryTruncated', 'truncatedForStorage'
  ]::text[] THEN RETURN 'unexpected_keys'; END IF;
  IF p_result->'projectionVersion' IS DISTINCT FROM '2'::jsonb THEN RETURN 'projection_version'; END IF;
  IF p_result->'source' IS DISTINCT FROM '"ai_extracted"'::jsonb THEN RETURN 'source'; END IF;
  IF jsonb_typeof(p_result->'summary') IS DISTINCT FROM 'string' THEN RETURN 'summary'; END IF;
  IF jsonb_typeof(p_result->'requirements') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_result->'requirements') > 200 THEN RETURN 'requirements'; END IF;
  IF jsonb_typeof(p_result->'importantDates') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_result->'importantDates') > 10 THEN RETURN 'important_dates'; END IF;
  IF jsonb_typeof(p_result->'missingInformation') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_result->'missingInformation') > 8 THEN RETURN 'missing_information'; END IF;
  IF jsonb_typeof(p_result->'truncatedForStorage') IS DISTINCT FROM 'boolean'
     OR jsonb_typeof(p_result->'summaryTruncated') IS DISTINCT FROM 'boolean' THEN RETURN 'truncation_flags'; END IF;
  IF jsonb_typeof(p_result->'omitted') IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_result#>'{omitted,requirements}') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_result#>'{omitted,importantDates}') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_result#>'{omitted,missingInformation}') IS DISTINCT FROM 'number' THEN RETURN 'omitted'; END IF;

  v_any_omitted := (p_result#>>'{omitted,requirements}')::numeric > 0
                OR (p_result#>>'{omitted,importantDates}')::numeric > 0
                OR (p_result#>>'{omitted,missingInformation}')::numeric > 0;
  IF (p_result->>'truncatedForStorage')::boolean
     IS DISTINCT FROM (v_any_omitted OR (p_result->>'summaryTruncated')::boolean) THEN
    RETURN 'truncation_flag_contradicts_counts';
  END IF;

  IF jsonb_typeof(p_result->'coverage') IS DISTINCT FROM 'object' THEN RETURN 'coverage'; END IF;
  v_status := p_result#>>'{coverage,status}';
  IF v_status IS NULL OR v_status NOT IN ('complete', 'incomplete') THEN RETURN 'coverage_status'; END IF;
  IF jsonb_typeof(p_result#>'{coverage,chunksTotal}') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_result#>'{coverage,chunksProcessed}') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_result#>'{coverage,chunks}') IS DISTINCT FROM 'array' THEN RETURN 'coverage_shape'; END IF;
  v_total := (p_result#>>'{coverage,chunksTotal}')::integer;
  v_processed := (p_result#>>'{coverage,chunksProcessed}')::integer;
  IF v_total < 1 OR v_total > 16 OR v_processed < 0 OR v_processed > v_total THEN RETURN 'coverage_counts'; END IF;
  IF jsonb_array_length(p_result#>'{coverage,chunks}') <> v_total THEN RETURN 'chunk_list_does_not_match_total'; END IF;
  SELECT count(*) INTO v_actual_processed
    FROM jsonb_array_elements(p_result#>'{coverage,chunks}') AS c
   WHERE c->>'outcome' = 'processed';
  IF v_actual_processed <> v_processed THEN RETURN 'processed_count_mismatch'; END IF;
  IF v_status = 'complete' AND v_processed <> v_total THEN RETURN 'complete_but_unprocessed_parts'; END IF;
  IF v_status = 'incomplete' AND (v_processed = v_total OR v_processed = 0) THEN RETURN 'incomplete_inconsistent'; END IF;
  RETURN NULL;
END;
$problem$;

-- 3. Saved analyses.
CREATE TABLE ghm.tender_analysis (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  business_id bigint NOT NULL REFERENCES ghm.business(id) ON DELETE RESTRICT,
  -- Deleting a tracking record keeps the saved analysis, unlinked.
  tender_tracking_id bigint REFERENCES ghm.tender_tracking(id) ON DELETE SET NULL,
  projection_version smallint NOT NULL DEFAULT 2,
  source text NOT NULL DEFAULT 'ai_extracted',
  model text NOT NULL,
  prompt_version text NOT NULL,
  -- Hash only; the document text is never stored (owner decision Q6).
  document_sha256 text NOT NULL,
  document_hash_version smallint NOT NULL DEFAULT 1,
  coverage_status text NOT NULL,
  chunks_total smallint NOT NULL,
  chunks_processed smallint NOT NULL,
  truncated_for_storage boolean NOT NULL,
  result jsonb NOT NULL,
  created_by bigint NOT NULL REFERENCES ghm.account_identity(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT tender_analysis_projection_version_valid CHECK (projection_version = 2),
  CONSTRAINT tender_analysis_source_valid CHECK (source = 'ai_extracted'),
  CONSTRAINT tender_analysis_model_valid
    CHECK (char_length(model) BETWEEN 1 AND 120 AND model = btrim(model)),
  CONSTRAINT tender_analysis_prompt_version_valid
    CHECK (char_length(prompt_version) BETWEEN 1 AND 60 AND prompt_version = btrim(prompt_version)),
  CONSTRAINT tender_analysis_document_hash_valid CHECK (document_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT tender_analysis_document_hash_version_valid CHECK (document_hash_version = 1),
  -- 'unsupported' has no representation.
  CONSTRAINT tender_analysis_coverage_status_valid CHECK (coverage_status IN ('complete', 'incomplete')),
  CONSTRAINT tender_analysis_chunk_counts_valid
    CHECK (chunks_total BETWEEN 1 AND 16 AND chunks_processed BETWEEN 0 AND chunks_total),
  CONSTRAINT tender_analysis_status_matches_counts
    CHECK ((coverage_status = 'complete') = (chunks_processed = chunks_total)),
  CONSTRAINT tender_analysis_result_structurally_valid
    CHECK (ghm.tender_analysis_result_problem(result) IS NULL),
  CONSTRAINT tender_analysis_columns_match_result CHECK (
    coverage_status = result#>>'{coverage,status}'
    AND chunks_total = (result#>>'{coverage,chunksTotal}')::integer
    AND chunks_processed = (result#>>'{coverage,chunksProcessed}')::integer
    AND truncated_for_storage = (result->>'truncatedForStorage')::boolean
  )
);
CREATE INDEX tender_analysis_business_idx ON ghm.tender_analysis (business_id, id DESC);
CREATE INDEX tender_analysis_tracking_idx ON ghm.tender_analysis (tender_tracking_id)
  WHERE tender_tracking_id IS NOT NULL;

-- Stored analyses are immutable. The ONLY permitted change is the foreign-key action that
-- unlinks the tracking record when that record is permanently deleted.
CREATE OR REPLACE FUNCTION ghm.guard_tender_analysis_update()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, ghm
AS $guard$
BEGIN
  IF NEW.tender_tracking_id IS NOT NULL
     OR (to_jsonb(NEW) - 'tender_tracking_id') IS DISTINCT FROM (to_jsonb(OLD) - 'tender_tracking_id') THEN
    RAISE EXCEPTION 'saved tender analyses are immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$guard$;
ALTER FUNCTION ghm.guard_tender_analysis_update() OWNER TO ghm_schema_owner;
REVOKE ALL ON FUNCTION ghm.guard_tender_analysis_update() FROM PUBLIC;
CREATE TRIGGER tender_analysis_immutable
BEFORE UPDATE ON ghm.tender_analysis
FOR EACH ROW EXECUTE FUNCTION ghm.guard_tender_analysis_update();

ALTER TABLE ghm.tender_analysis OWNER TO ghm_schema_owner;
ALTER TABLE ghm.tender_analysis ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE ghm.tender_analysis FROM PUBLIC, ghm_runtime, ghm_migrator, ghm_actor_gateway;
REVOKE ALL ON SEQUENCE ghm.tender_analysis_id_seq FROM PUBLIC, ghm_runtime, ghm_migrator, ghm_actor_gateway;

-- 4. The assertion verifier now also accepts the four analysis operations. Same signature,
--    so CREATE OR REPLACE keeps the owner and the (empty) ACL from the tracking migration.
CREATE OR REPLACE FUNCTION ghm.verify_tender_gateway_assertion(
  p_actor bigint,
  p_issued bigint,
  p_nonce uuid,
  p_operation text,
  p_context text,
  p_signature text
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, ghm, pg_temp
AS $verify$
DECLARE
  v_secret bytea;
  v_expected bytea;
  v_provided bytea;
  v_payload text;
  v_diff integer := 0;
  v_i integer;
BEGIN
  IF session_user <> 'ghm_actor_gateway'
     OR p_actor IS NULL OR p_actor <= 0
     OR p_issued IS NULL OR p_nonce IS NULL
     OR p_operation IS NULL
     OR p_operation NOT IN (
       'tender.tracking.create', 'tender.tracking.list', 'tender.tracking.get',
       'tender.tracking.update', 'tender.tracking.archive', 'tender.tracking.delete',
       'tender.analysis.create', 'tender.analysis.list', 'tender.analysis.get',
       'tender.analysis.delete'
     )
     OR p_context IS NULL
     OR octet_length(convert_to(p_context, 'UTF8')) > 32768
     OR p_signature IS NULL OR p_signature !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Invalid tender gateway assertion' USING ERRCODE = '42501';
  END IF;

  IF abs(extract(epoch FROM clock_timestamp())::bigint - p_issued) > 60 THEN
    RAISE EXCEPTION 'Tender gateway assertion expired' USING ERRCODE = '42501';
  END IF;

  SELECT secret INTO v_secret
    FROM ghm.actor_gateway_capability_assertion_secret
   WHERE singleton = true;
  IF v_secret IS NULL OR octet_length(v_secret) <> 32 THEN
    RAISE EXCEPTION 'Actor assertion verifier is not provisioned' USING ERRCODE = '42501';
  END IF;

  v_payload := 'ghm-actor-gateway:v2|' || p_actor::text || '|' || p_operation || '|' ||
               p_issued::text || '|' || p_nonce::text || '|' ||
               encode(convert_to(p_context, 'UTF8'), 'hex');
  v_expected := public.hmac(convert_to(v_payload, 'UTF8'), v_secret, 'sha256');
  v_provided := decode(p_signature, 'hex');
  FOR v_i IN 0..31 LOOP
    v_diff := v_diff | (get_byte(v_expected, v_i) # get_byte(v_provided, v_i));
  END LOOP;
  IF v_diff <> 0 THEN
    RAISE EXCEPTION 'Tender gateway assertion signature invalid' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM ghm.account_identity ai
     WHERE ai.id = p_actor
       AND ai.account_status = 'active'
  ) THEN
    RAISE EXCEPTION 'Active GHM account required' USING ERRCODE = '42501';
  END IF;

  DELETE FROM ghm.actor_gateway_capability_assertion_nonce
   WHERE expires_at < clock_timestamp();
  BEGIN
    INSERT INTO ghm.actor_gateway_capability_assertion_nonce(nonce, expires_at)
    VALUES (
      p_nonce,
      GREATEST(clock_timestamp(), to_timestamp(p_issued)) + interval '60 seconds'
    );
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Tender gateway assertion replay detected' USING ERRCODE = '42501';
  END;
END;
$verify$;
ALTER FUNCTION ghm.verify_tender_gateway_assertion(bigint,bigint,uuid,text,text,text)
  OWNER TO ghm_schema_owner;
REVOKE ALL ON FUNCTION ghm.verify_tender_gateway_assertion(bigint,bigint,uuid,text,text,text)
  FROM PUBLIC, ghm_runtime, ghm_migrator, ghm_actor_gateway;

-- 5. Row -> JSON. Metadata never includes the payload; the full record adds `result`.
CREATE OR REPLACE FUNCTION ghm.tender_analysis_json(p_row ghm.tender_analysis, p_with_result boolean)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, ghm
AS $json$
  SELECT jsonb_build_object(
    'id', p_row.id,
    'businessId', p_row.business_id,
    'trackingId', p_row.tender_tracking_id,
    'model', p_row.model,
    'promptVersion', p_row.prompt_version,
    'documentSha256', p_row.document_sha256,
    'documentHashVersion', p_row.document_hash_version,
    'projectionVersion', p_row.projection_version,
    'source', p_row.source,
    'coverageStatus', p_row.coverage_status,
    'chunksTotal', p_row.chunks_total,
    'chunksProcessed', p_row.chunks_processed,
    'truncatedForStorage', p_row.truncated_for_storage,
    'createdBy', p_row.created_by,
    'createdAt', p_row.created_at
  ) || CASE WHEN p_with_result THEN jsonb_build_object('result', p_row.result) ELSE '{}'::jsonb END;
$json$;

CREATE OR REPLACE FUNCTION ghm.gateway_create_tender_analysis(
  p_actor bigint,
  p_issued bigint,
  p_nonce uuid,
  p_context text,
  p_signature text,
  p_business_id bigint,
  p_tracking_id bigint,
  p_model text,
  p_prompt_version text,
  p_document_sha256 text,
  p_result jsonb,
  p_request_id uuid,
  p_client_correlation_id uuid
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, ghm, pg_temp
AS $create$
DECLARE
  v_row ghm.tender_analysis;
  v_count integer;
BEGIN
  IF p_context::jsonb IS DISTINCT FROM jsonb_build_object(
    'businessId', p_business_id,
    'trackingId', p_tracking_id,
    'model', p_model,
    'promptVersion', p_prompt_version,
    'documentSha256', p_document_sha256,
    'documentHashVersion', 1,
    'result', p_result,
    'requestId', p_request_id::text,
    'clientCorrelationId', p_client_correlation_id::text
  ) THEN
    RAISE EXCEPTION 'Tender gateway assertion context mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM ghm.verify_tender_gateway_assertion(
    p_actor, p_issued, p_nonce, 'tender.analysis.create', p_context, p_signature
  );
  PERFORM ghm.require_tender_business_membership(p_actor, p_business_id, false);

  -- Second line only: the Gateway validator has already applied the full version-2 contract.
  IF p_request_id IS NULL
     OR p_model IS NULL OR p_model <> btrim(p_model) OR char_length(p_model) NOT BETWEEN 1 AND 120
     OR p_prompt_version IS NULL OR p_prompt_version <> btrim(p_prompt_version)
     OR char_length(p_prompt_version) NOT BETWEEN 1 AND 60
     OR p_document_sha256 IS NULL OR p_document_sha256 !~ '^[0-9a-f]{64}$'
     OR (p_tracking_id IS NOT NULL AND p_tracking_id <= 0)
     OR ghm.tender_analysis_result_problem(p_result) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid tender analysis request' USING ERRCODE = '22023';
  END IF;

  -- Serialise creates per Business so the cap cannot be raced past.
  PERFORM pg_advisory_xact_lock(hashtextextended('tender-analysis:' || p_business_id::text, 0));
  SELECT count(*) INTO v_count FROM ghm.tender_analysis a WHERE a.business_id = p_business_id;
  IF v_count >= 100 THEN
    RAISE EXCEPTION 'Tender analysis limit reached' USING ERRCODE = 'P0001';
  END IF;

  -- A linked tracking record must belong to THIS Business. A record of another Business is
  -- indistinguishable from a missing one.
  IF p_tracking_id IS NOT NULL THEN
    PERFORM 1 FROM ghm.tender_tracking t
     WHERE t.id = p_tracking_id AND t.business_id = p_business_id
       FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Tender tracking record not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  INSERT INTO ghm.tender_analysis (
    business_id, tender_tracking_id, projection_version, source, model, prompt_version,
    document_sha256, document_hash_version, coverage_status, chunks_total, chunks_processed,
    truncated_for_storage, result, created_by
  ) VALUES (
    p_business_id, p_tracking_id, 2, 'ai_extracted', p_model, p_prompt_version,
    p_document_sha256, 1,
    p_result#>>'{coverage,status}',
    (p_result#>>'{coverage,chunksTotal}')::smallint,
    (p_result#>>'{coverage,chunksProcessed}')::smallint,
    (p_result->>'truncatedForStorage')::boolean,
    p_result, p_actor
  )
  RETURNING * INTO v_row;

  PERFORM ghm.record_tender_audit_event(
    p_request_id, p_client_correlation_id, p_actor, p_business_id,
    'tender.analysis.create', 'analysis', v_row.id,
    jsonb_build_object(
      'coverageStatus', v_row.coverage_status,
      'chunksTotal', v_row.chunks_total,
      'chunksProcessed', v_row.chunks_processed,
      'truncatedForStorage', v_row.truncated_for_storage,
      'documentSha256', v_row.document_sha256,
      'trackingLinked', v_row.tender_tracking_id IS NOT NULL
    )
  );

  RETURN ghm.tender_analysis_json(v_row, true);
END;
$create$;

CREATE OR REPLACE FUNCTION ghm.gateway_list_tender_analysis(
  p_actor bigint,
  p_issued bigint,
  p_nonce uuid,
  p_context text,
  p_signature text,
  p_business_id bigint,
  p_limit integer,
  p_after bigint
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, ghm, pg_temp
AS $list$
DECLARE
  v_items jsonb;
  v_last bigint;
  v_count integer;
BEGIN
  IF p_context::jsonb IS DISTINCT FROM jsonb_build_object(
    'businessId', p_business_id,
    'limit', p_limit,
    'after', p_after
  ) THEN
    RAISE EXCEPTION 'Tender gateway assertion context mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM ghm.verify_tender_gateway_assertion(
    p_actor, p_issued, p_nonce, 'tender.analysis.list', p_context, p_signature
  );
  PERFORM ghm.require_tender_business_membership(p_actor, p_business_id, false);

  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR (p_after IS NOT NULL AND p_after <= 0) THEN
    RAISE EXCEPTION 'Invalid tender analysis request' USING ERRCODE = '22023';
  END IF;

  -- Metadata only: the payload (up to 12 KiB each) is returned by the single-record read.
  SELECT coalesce(jsonb_agg(ghm.tender_analysis_json(t.r, false) ORDER BY (t.r).id DESC), '[]'::jsonb),
         count(*),
         min((t.r).id)
    INTO v_items, v_count, v_last
    FROM (
      SELECT x AS r
        FROM ghm.tender_analysis x
       WHERE x.business_id = p_business_id
         AND (p_after IS NULL OR x.id < p_after)
       ORDER BY x.id DESC
       LIMIT p_limit
    ) t;

  RETURN jsonb_build_object(
    'items', v_items,
    'nextAfter', CASE WHEN v_count = p_limit THEN v_last ELSE NULL END
  );
END;
$list$;

CREATE OR REPLACE FUNCTION ghm.gateway_get_tender_analysis(
  p_actor bigint,
  p_issued bigint,
  p_nonce uuid,
  p_context text,
  p_signature text,
  p_business_id bigint,
  p_analysis_id bigint
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, ghm, pg_temp
AS $get$
DECLARE
  v_row ghm.tender_analysis;
BEGIN
  IF p_context::jsonb IS DISTINCT FROM jsonb_build_object(
    'businessId', p_business_id,
    'analysisId', p_analysis_id
  ) THEN
    RAISE EXCEPTION 'Tender gateway assertion context mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM ghm.verify_tender_gateway_assertion(
    p_actor, p_issued, p_nonce, 'tender.analysis.get', p_context, p_signature
  );
  PERFORM ghm.require_tender_business_membership(p_actor, p_business_id, false);

  IF p_analysis_id IS NULL OR p_analysis_id <= 0 THEN
    RAISE EXCEPTION 'Invalid tender analysis request' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row
    FROM ghm.tender_analysis a
   WHERE a.id = p_analysis_id
     AND a.business_id = p_business_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tender analysis not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN ghm.tender_analysis_json(v_row, true);
END;
$get$;

-- Permanent deletion of a saved analysis (owner/administrator). There is no archive for
-- analyses. The audit event has no foreign key to the analysis, so it survives.
CREATE OR REPLACE FUNCTION ghm.gateway_delete_tender_analysis(
  p_actor bigint,
  p_issued bigint,
  p_nonce uuid,
  p_context text,
  p_signature text,
  p_business_id bigint,
  p_analysis_id bigint,
  p_request_id uuid,
  p_client_correlation_id uuid
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, ghm, pg_temp
AS $delete$
DECLARE
  v_row ghm.tender_analysis;
BEGIN
  IF p_context::jsonb IS DISTINCT FROM jsonb_build_object(
    'businessId', p_business_id,
    'analysisId', p_analysis_id,
    'requestId', p_request_id::text,
    'clientCorrelationId', p_client_correlation_id::text
  ) THEN
    RAISE EXCEPTION 'Tender gateway assertion context mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM ghm.verify_tender_gateway_assertion(
    p_actor, p_issued, p_nonce, 'tender.analysis.delete', p_context, p_signature
  );
  PERFORM ghm.require_tender_business_membership(p_actor, p_business_id, true);

  IF p_request_id IS NULL OR p_analysis_id IS NULL OR p_analysis_id <= 0 THEN
    RAISE EXCEPTION 'Invalid tender analysis request' USING ERRCODE = '22023';
  END IF;

  DELETE FROM ghm.tender_analysis a
   WHERE a.id = p_analysis_id
     AND a.business_id = p_business_id
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tender analysis not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM ghm.record_tender_audit_event(
    p_request_id, p_client_correlation_id, p_actor, p_business_id,
    'tender.analysis.delete', 'analysis', v_row.id,
    jsonb_build_object(
      'coverageStatus', v_row.coverage_status,
      'documentSha256', v_row.document_sha256
    )
  );

  RETURN jsonb_build_object('id', v_row.id, 'businessId', v_row.business_id, 'deleted', true);
END;
$delete$;

-- Ownership and grants. Internal helpers: executable by nobody. Gateway functions: the Actor
-- Gateway login only.
ALTER FUNCTION ghm.tender_analysis_result_problem(jsonb) OWNER TO ghm_schema_owner;
ALTER FUNCTION ghm.tender_analysis_json(ghm.tender_analysis, boolean) OWNER TO ghm_schema_owner;
ALTER FUNCTION ghm.gateway_create_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint,text,text,text,jsonb,uuid,uuid)
  OWNER TO ghm_schema_owner;
ALTER FUNCTION ghm.gateway_list_tender_analysis(bigint,bigint,uuid,text,text,bigint,integer,bigint)
  OWNER TO ghm_schema_owner;
ALTER FUNCTION ghm.gateway_get_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint)
  OWNER TO ghm_schema_owner;
ALTER FUNCTION ghm.gateway_delete_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint,uuid,uuid)
  OWNER TO ghm_schema_owner;

REVOKE ALL ON FUNCTION ghm.tender_analysis_result_problem(jsonb)
  FROM PUBLIC, ghm_runtime, ghm_migrator, ghm_actor_gateway;
REVOKE ALL ON FUNCTION ghm.tender_analysis_json(ghm.tender_analysis, boolean)
  FROM PUBLIC, ghm_runtime, ghm_migrator, ghm_actor_gateway;

REVOKE ALL ON FUNCTION ghm.gateway_create_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint,text,text,text,jsonb,uuid,uuid)
  FROM PUBLIC, ghm_runtime, ghm_migrator;
REVOKE ALL ON FUNCTION ghm.gateway_list_tender_analysis(bigint,bigint,uuid,text,text,bigint,integer,bigint)
  FROM PUBLIC, ghm_runtime, ghm_migrator;
REVOKE ALL ON FUNCTION ghm.gateway_get_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint)
  FROM PUBLIC, ghm_runtime, ghm_migrator;
REVOKE ALL ON FUNCTION ghm.gateway_delete_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint,uuid,uuid)
  FROM PUBLIC, ghm_runtime, ghm_migrator;

GRANT EXECUTE ON FUNCTION ghm.gateway_create_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint,text,text,text,jsonb,uuid,uuid)
  TO ghm_actor_gateway;
GRANT EXECUTE ON FUNCTION ghm.gateway_list_tender_analysis(bigint,bigint,uuid,text,text,bigint,integer,bigint)
  TO ghm_actor_gateway;
GRANT EXECUTE ON FUNCTION ghm.gateway_get_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint)
  TO ghm_actor_gateway;
GRANT EXECUTE ON FUNCTION ghm.gateway_delete_tender_analysis(bigint,bigint,uuid,text,text,bigint,bigint,uuid,uuid)
  TO ghm_actor_gateway;

COMMENT ON TABLE ghm.tender_analysis IS
  'Saved ZAID Tender AI analyses (version 2 projection). Reachable only through ghm.gateway_*_tender_analysis functions. Immutable; hash only, never document text; unsupported analyses have no representation.';

COMMIT;
